CREATE OR REPLACE FUNCTION check_premature_resolution()
RETURNS TRIGGER AS $ 
BEGIN 
    IF NEW.resstat = 'Resolved' AND OLD.resstat != 'In Progress' THEN 
        RAISE EXCEPTION 'Premature Resolution Block: Cannot resolve unless status is In Progress.';
    END IF;
    RETURN NEW;
END; 
$ LANGUAGE plpgsql;

CREATE TRIGGER resolution_check
BEFORE UPDATE ON enforcementactions
FOR EACH ROW EXECUTE FUNCTION check_premature_resolution();

